<?php
function receipt_archive_query($input){
 $where=["batch_type='Receipt PDF'"];$args=[];$filters=[];
 foreach(['from_date','to_date'] as $key){$v=trim((string)($input[$key]??''));if($v!==''){$d=DateTime::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new Exception('Select a valid date.');$where[]='txn_date '.($key==='from_date'?'>=':'<=').' ?';$args[]=$v;}$filters[$key]=$v;}
 if($filters['from_date']&&$filters['to_date']&&$filters['from_date']>$filters['to_date'])throw new Exception('To Date must be on or after From Date.');
 $v=trim((string)($input['source']??''));$filters['source']=$v;if($v!==''){$where[]='source_name=?';$args[]=$v;}$status=receipt_archive_status(trim((string)($input['receipt_status']??'')));$filters['receipt_status']=$status;if($status!==''){$stored=db()->query("SELECT DISTINCT status FROM inflow_batches WHERE batch_type='Receipt PDF'")->fetchAll(PDO::FETCH_COLUMN);$matches=array_values(array_filter($stored,fn($s)=>receipt_archive_status($s)===$status));if(!$matches)$where[]='0=1';else{$where[]='status IN ('.implode(',',array_fill(0,count($matches),'?')).')';array_push($args,...$matches);}}
 return ['where'=>implode(' AND ',$where),'args'=>$args,'filters'=>$filters];
}
function receipt_archive_status($status){return ['Confirmed'=>'Posted','Complete'=>'Posted','Successful'=>'Posted','Error'=>'Needs Correction','Incomplete'=>'Needs Correction','Unsuccessful'=>'Needs Correction','Partial / With Errors'=>'Needs Correction','Review'=>'Pending Review','Draft'=>'Pending Review','To Review'=>'Pending Review'][$status]??$status;}
echo '<div class="page-head"><div><h1>Receipt Archive</h1><p>Original packing slips and delivery receipts linked to inflow transactions.</p></div></div>';
try{$filter=receipt_archive_query($_GET);$f=$filter['filters'];$total=rs8_list_total('SELECT COUNT(*) FROM inflow_batches WHERE '.$filter['where'],$filter['args']);$offset=min(max(0,intdiv((int)($_GET['offset']??0),10)*10),max(0,(int)ceil($total/10)-1)*10);
echo '<div class="card"><form method="get" class="setup-receipt-filters"><input type="hidden" name="page" value="receipts"><label>From Date<input type="date" name="from_date" value="'.e($f['from_date']).'"></label><label>To Date<input type="date" name="to_date" value="'.e($f['to_date']).'"></label><label>Source<select name="source"><option value="">All Sources</option>';
foreach(db()->query("SELECT DISTINCT source_name FROM inflow_batches WHERE batch_type='Receipt PDF' AND source_name<>'' ORDER BY source_name")->fetchAll(PDO::FETCH_COLUMN) as $source)echo '<option value="'.e($source).'" '.($f['source']===$source?'selected':'').'>'.e($source).'</option>';
echo '</select></label><label>Status<select name="receipt_status"><option value="">All Statuses</option>';
foreach(array_unique(array_map('receipt_archive_status',db()->query("SELECT DISTINCT status FROM inflow_batches WHERE batch_type='Receipt PDF' ORDER BY status")->fetchAll(PDO::FETCH_COLUMN))) as $status)echo '<option value="'.e($status).'" '.($f['receipt_status']===$status?'selected':'').'>'.e(receipt_archive_status($status)).'</option>';
echo '</select></label><div class="setup-filter-actions"><a class="btn ghost" href="?page=receipts">Clear Filters</a><button class="btn primary">Apply Filters</button></div></form></div><div class="card table-wrap setup-receipts"><div class="card-head"><div><h3>Archived Receipts</h3><p class="muted small">'.number_format($total).' matching receipts · 10 per page</p></div></div><div class="setup-receipt-table"><table class="table"><thead><tr><th>Date</th><th>Reference</th><th>Transfer Ref</th><th>Source</th><th>File</th><th>Status</th><th>Action</th></tr></thead><tbody>';
$q=db()->prepare('SELECT * FROM inflow_batches WHERE '.$filter['where'].' ORDER BY txn_date DESC,id DESC LIMIT 10 OFFSET '.$offset);$q->execute($filter['args']);foreach($q as $r)echo '<tr><td>'.e($r['txn_date']).'</td><td>'.e($r['reference_no']).'</td><td>'.e($r['transfer_ref']?:'—').'</td><td>'.e($r['source_name']).'</td><td>'.e($r['original_filename']).'</td><td>'.badge(receipt_archive_status($r['status']),['Needs Correction'=>'danger','Posted'=>'ok','Pending Review'=>'warn','Cancelled'=>'info'][receipt_archive_status($r['status'])]??status_badge_class($r['status'])).'</td><td><div class="setup-row-actions"><a class="btn ghost sm" href="?page='.($r['status']==='Confirmed'?'inflow_batch':'receipt_review').'&id='.$r['id'].'">View</a><a class="btn ghost sm" target="_blank" rel="noopener" href="download.php?type=receipt&id='.$r['id'].'">PDF</a>'.inflow_error_review_link($r).'</div></td></tr>';
if(!$total)echo '<tr><td colspan="7">No receipts match the selected filters.</td></tr>';echo '</tbody></table></div></div>';echo rs8_pagination($total,$offset,10,array_replace($_GET,['page'=>'receipts']));
}catch(Throwable $ex){echo '<div class="alert danger">'.e(safe_error_message($ex)).'</div><a class="btn ghost" href="?page=receipts">Clear Filters</a>';}
